package com.gasczoology.invertebratelab.data

/**
 * Five-mark practice questions for the Unit VI extension chapters. DRAFT_UNVERIFIED:
 * written by the assistant from the chapter text, not from the validated A5 JSON, and
 * the Tamil needs the author's review. Two questions per chapter, five answer points each.
 * These are NOT part of the validated 86-question corpus.
 */
object InsectaQuestions {
    private fun q(chapterId: String, n: Int, en: String, ta: String, vararg points: Pair<String, String>) = A5Question(
        id = "$chapterId-A5-$n",
        chapterId = chapterId,
        question = BilingualText(en, ta),
        answerPoints = points.map { BilingualText(it.first, it.second) },
    )

    val byChapter: Map<String, List<A5Question>> = listOf(
        q("u6-insecta", 1, "Give the general characters of Class Insecta.", "பூச்சி வகுப்பின் பொதுப் பண்புகளைத் தருக.",
            "The body is divided into head, thorax and abdomen." to "உடல் தலை, மார்பு, வயிறு எனப் பிரிந்துள்ளது.",
            "The head bears one pair of antennae, compound eyes and mouthparts." to "தலையில் ஒரு இணை உணர்கொம்புகள், கூட்டுக்கண்கள், வாயுறுப்புகள் உள்ளன.",
            "The thorax bears three pairs of jointed legs and usually two pairs of wings." to "மார்பில் மூன்று இணை மூட்டுக் கால்களும் பொதுவாக இரு இணை இறக்கைகளும் உள்ளன.",
            "Respiration is by a tracheal system opening through spiracles." to "சுவாசம் ஸ்பைராக்கிள்கள் வழி திறக்கும் மூச்சுக்குழல் தொகுதியால் நடைபெறுகிறது.",
            "Excretion is by Malpighian tubules, and development is by metamorphosis." to "கழிவு நீக்கம் மால்பீஜியன் குழல்களால்; வளர்ச்சி உருமாற்றம் வழி நடைபெறுகிறது."),
        q("u6-insecta", 2, "Compare complete and incomplete metamorphosis with examples.", "முழு உருமாற்றத்தையும் முழுமையற்ற உருமாற்றத்தையும் எடுத்துக்காட்டுகளுடன் ஒப்பிடுக.",
            "In complete metamorphosis there are four stages: egg, larva, pupa and adult." to "முழு உருமாற்றத்தில் முட்டை, புழு, கூட்டுப்புழு, முதிர்பூச்சி என நான்கு நிலைகள் உள்ளன.",
            "The larva differs greatly from the adult, as a caterpillar differs from a moth." to "புழு முதிர்பூச்சியிலிருந்து பெரிதும் வேறுபடுகிறது; எ.கா. கம்பளிப்புழுவும் அந்துப்பூச்சியும்.",
            "In incomplete metamorphosis there are three stages: egg, nymph and adult, with no pupa." to "முழுமையற்ற உருமாற்றத்தில் முட்டை, இளவுயிரி, முதிர்பூச்சி என மூன்று நிலைகள்; கூட்டுப்புழு இல்லை.",
            "The nymph resembles the adult and grows by moulting, as in the cockroach and the grasshopper." to "இளவுயிரி முதிர்பூச்சியை ஒத்து உரித்தலால் வளர்கிறது; எ.கா. கரப்பான், வெட்டுக்கிளி.",
            "Beetles, flies, butterflies and bees show complete metamorphosis." to "வண்டுகள், ஈக்கள், பட்டாம்பூச்சிகள், தேனீக்கள் முழு உருமாற்றம் காட்டுகின்றன."),

        q("u6-cockroach", 1, "Describe the digestive system of the cockroach.", "கரப்பான் பூச்சியின் செரிமானத் தொகுதியை விவரிக்க.",
            "The alimentary canal has a foregut, midgut and hindgut." to "உணவுக்குழல் முன்குடல், நடுக்குடல், பின்குடல் ஆகியவற்றைக் கொண்டுள்ளது.",
            "The foregut includes the pharynx, oesophagus, crop and gizzard." to "முன்குடலில் தொண்டை, உணவுக்குழாய், கிராப், கிஸார்டு உள்ளன.",
            "The gizzard has chitinous teeth that grind the food." to "கிஸார்டில் உணவை அரைக்கும் கைட்டின் பற்கள் உள்ளன.",
            "Hepatic caecae at the junction of foregut and midgut secrete digestive enzymes." to "முன்குடல்-நடுக்குடல் சந்திப்பிலுள்ள கல்லீரல் குருட்டுக்குழல்கள் செரிமான நொதிகளைச் சுரக்கின்றன.",
            "Absorption is in the midgut, and the hindgut ends in the rectum and anus." to "உறிஞ்சுதல் நடுக்குடலில்; பின்குடல் மலக்குடலிலும் குதத்திலும் முடிகிறது."),
        q("u6-cockroach", 2, "Explain respiration and circulation in the cockroach.", "கரப்பான் பூச்சியின் சுவாசத்தையும் இரத்தச் சுற்றோட்டத்தையும் விளக்குக.",
            "Respiration is by tracheae, branching air tubes that carry oxygen directly to the tissues." to "சுவாசம் மூச்சுக்குழல்களால்; கிளைத்த காற்றுக்குழாய்கள் ஆக்சிஜனை நேரடியாகத் திசுக்களுக்குக் கொண்டு செல்கின்றன.",
            "Air enters through ten pairs of spiracles on the thorax and abdomen." to "மார்பிலும் வயிற்றிலும் உள்ள பத்து இணை ஸ்பைராக்கிள்கள் வழியாகக் காற்று நுழைகிறது.",
            "The circulatory system is open, with a tubular heart and a haemocoel." to "சுற்றோட்டத் தொகுதி திறந்தது; குழல் வடிவ இதயமும் இரத்தக்குழியும் உள்ளன.",
            "The haemolymph is colourless and carries nutrients, not oxygen." to "இரத்தநிணநீர் நிறமற்றது; ஊட்டச்சத்துகளைக் கொண்டு செல்கிறது, ஆக்சிஜனை அல்ல.",
            "Blood flows into the heart through ostia, and is pumped forwards." to "இரத்தம் துளைகள் (ostia) வழியாக இதயத்தில் நுழைந்து முன்னோக்கிச் செலுத்தப்படுகிறது."),

        q("u6-pollinators", 1, "What is pollination? Name its types and the insect groups that pollinate.", "மகரந்தச் சேர்க்கை என்றால் என்ன? அதன் வகைகளையும் மகரந்தச் சேர்க்கை செய்யும் பூச்சிக் குழுக்களையும் குறிப்பிடுக.",
            "Pollination is the transfer of pollen from the anther to the stigma." to "மகரந்தம் மகரந்தப்பையிலிருந்து சூலகமுடிக்கு மாற்றப்படுவது மகரந்தச் சேர்க்கை.",
            "It is self-pollination when pollen reaches a flower of the same plant, and cross-pollination when it reaches another plant." to "அதே தாவரத்தின் பூவுக்குச் சென்றால் தன் மகரந்தச் சேர்க்கை; வேறு தாவரத்துக்குச் சென்றால் அயல் மகரந்தச் சேர்க்கை.",
            "Pollination by insects is called entomophily." to "பூச்சிகளால் நடைபெறும் மகரந்தச் சேர்க்கை பூச்சி மகரந்தச் சேர்க்கை (Entomophily).",
            "Bees, butterflies, moths, flies and beetles are the main insect pollinators." to "தேனீக்கள், பட்டாம்பூச்சிகள், அந்துப்பூச்சிகள், ஈக்கள், வண்டுகள் முக்கிய பூச்சி மகரந்தச் சேர்க்கையாளர்கள்.",
            "Insect-pollinated flowers have bright petals, scent or nectar and sticky pollen." to "பூச்சி மகரந்தச் சேர்க்கைப் பூக்களுக்குப் பளிச்சென்ற இதழ்கள், மணம் அல்லது தேன், ஒட்டும் மகரந்தம் உண்டு."),
        q("u6-pollinators", 2, "Describe the honeybee colony and its importance to agriculture.", "தேனீக் கூட்டத்தையும் வேளாண்மைக்கு அதன் முக்கியத்துவத்தையும் விவரிக்க.",
            "A colony has a single queen, many sterile female workers and seasonal male drones." to "ஒரு கூட்டத்தில் ஒரே ராணி, பல மலட்டுப் பெண் வேலைக்காரத் தேனீக்கள், பருவகால ஆண் தேனீக்கள் உள்ளன.",
            "The queen lays the eggs, and the drones mate with a queen." to "ராணி முட்டையிடுகிறது; ஆண் தேனீக்கள் ராணியுடன் இணைகின்றன.",
            "Workers collect nectar and pollen, make wax comb, feed the larvae and guard the hive." to "வேலைக்காரத் தேனீக்கள் தேனும் மகரந்தமும் சேகரித்து, மெழுகுக் கூடு கட்டி, புழுக்களுக்கு ஊட்டி, கூட்டைக் காக்கின்றன.",
            "Honeybees give honey, wax and other hive products." to "தேனீக்கள் தேன், மெழுகு, பிற கூட்டுப் பொருட்களைத் தருகின்றன.",
            "Their pollination raises the yield of many crops, which is often worth more than the honey." to "அவற்றின் மகரந்தச் சேர்க்கை பல பயிர்களின் மகசூலை உயர்த்துகிறது; இது பெரும்பாலும் தேனைவிட மதிப்புள்ளது."),

        q("u6-natural-enemies", 1, "Distinguish predators from parasitoids with examples.", "வேட்டையாடிகளையும் ஒட்டுண்ணிக்கொல்லிகளையும் எடுத்துக்காட்டுகளுடன் வேறுபடுத்துக.",
            "A predator kills and eats many prey during its life." to "வேட்டையாடி தன் வாழ்நாளில் பல இரைகளைக் கொன்று உண்கிறது.",
            "Ladybird beetles, lacewings, dragonflies and mantids are predators." to "லேடிபறவை வண்டுகள், லேஸ்விங்குகள், தட்டான்கள், மான்டிஸ்கள் வேட்டையாடிகள்.",
            "A parasitoid develops on or in one host and kills it." to "ஒட்டுண்ணிக்கொல்லி ஒரு விருந்தோம்பியின் மேலோ உள்ளோ வளர்ந்து அதைக் கொல்கிறது.",
            "Only the larva is parasitic; the adult is free-living." to "புழு மட்டுமே ஒட்டுண்ணி; முதிர்பூச்சி தனித்து வாழ்கிறது.",
            "Trichogramma, an egg parasitoid wasp, is a well-known example." to "முட்டை ஒட்டுண்ணிக் குளவி டிரைக்கோகிராம்மா நன்கு அறியப்பட்ட எடுத்துக்காட்டு."),
        q("u6-natural-enemies", 2, "Explain biological control and state its merits.", "உயிரியல் கட்டுப்பாட்டை விளக்கி அதன் நன்மைகளைக் கூறுக.",
            "Biological control uses living natural enemies to keep a pest below the damaging level." to "உயிரியல் கட்டுப்பாடு பீடையை சேதம் தரும் அளவுக்குக் கீழே வைக்க உயிருள்ள இயற்கை எதிரிகளைப் பயன்படுத்துகிறது.",
            "It may be done by importing, conserving or mass-releasing the enemy." to "எதிரியை இறக்குமதி செய்தல், காத்தல் அல்லது பெருமளவில் விடுவித்தல் மூலம் இதைச் செய்யலாம்.",
            "It leaves no poisonous residue on food or in the environment." to "உணவிலோ சூழலிலோ நச்சு எச்சம் எதுவும் இல்லை.",
            "A self-reproducing enemy can give lasting control at low cost." to "தானே பெருகும் எதிரி குறைந்த செலவில் நீடித்த கட்டுப்பாட்டைத் தரும்.",
            "It does not cause the resistance that repeated chemical sprays do." to "மீண்டும் மீண்டும் வேதித் தெளிப்பு உண்டாக்கும் எதிர்ப்பை இது உண்டாக்குவதில்லை."),

        q("u6-medical-insects", 1, "Describe how insects spread disease.", "பூச்சிகள் நோய்களை எவ்வாறு பரப்புகின்றன என்பதை விவரிக்க.",
            "Insects may carry germs on the body or legs, which is mechanical transmission, as the housefly does." to "பூச்சிகள் உடலிலோ கால்களிலோ கிருமிகளைச் சுமக்கலாம்; இது இயந்திர முறைப் பரவல்; எ.கா. வீட்டு ஈ.",
            "In biological transmission the germ develops or multiplies in the insect." to "உயிரியல் முறைப் பரவலில் கிருமி பூச்சிக்குள் வளர்கிறது அல்லது பெருகுகிறது.",
            "The insect then passes the germ on by its bite or its faeces." to "பூச்சி கடித்தல் அல்லது மலத்தால் கிருமியைக் கடத்துகிறது.",
            "Mosquitoes transmit malaria, filariasis and dengue." to "கொசுக்கள் மலேரியா, யானைக்கால், டெங்குவைப் பரப்புகின்றன.",
            "Fleas and lice also carry disease agents." to "பிளைகளும் பேன்களும் நோய்க் காரணிகளைக் கொண்டு செல்கின்றன."),
        q("u6-medical-insects", 2, "Explain the control of mosquitoes.", "கொசுக்களின் கட்டுப்பாட்டை விளக்குக.",
            "Remove or drain the stagnant water in which mosquitoes breed." to "கொசுக்கள் பெருகும் தேங்கிய நீரை அகற்றுதல் அல்லது வடித்தல்.",
            "Cover water containers and clean the water tanks." to "நீர்க்கலன்களை மூடி, தொட்டிகளைத் தூய்மைப்படுத்துதல்.",
            "Introduce larvivorous fish, such as Gambusia, in ponds." to "குளங்களில் Gambusia போன்ற புழுவுண்ணும் மீன்களை விடுதல்.",
            "Use nets, screens and repellents to prevent bites." to "கடிப்பதைத் தடுக்க வலைகள், திரைகள், விரட்டிகளைப் பயன்படுத்துதல்.",
            "Approved larvicides and fogging are used by health workers as part of integrated vector management." to "ஒருங்கிணைந்த கடத்தி மேலாண்மையின் பகுதியாகச் சுகாதாரப் பணியாளர்கள் அங்கீகரிக்கப்பட்ட புழுக்கொல்லிகளையும் புகைமூட்டலையும் பயன்படுத்துகின்றனர்."),

        q("u6-household-insects", 1, "Describe the termite colony and the damage that termites cause.", "கரையான் கூட்டத்தையும் கரையான்கள் உண்டாக்கும் சேதத்தையும் விவரிக்க.",
            "Termites are social insects that live in colonies with castes." to "கரையான்கள் சாதிகளுடன் கூட்டமாக வாழும் சமூகப் பூச்சிகள்.",
            "The castes are the king, queen, workers, soldiers and reproductives." to "சாதிகள்: அரசன், அரசி, வேலைக்காரர், போர்வீரர், இனப்பெருக்கிகள்.",
            "Workers feed the colony and build the nest; soldiers defend it." to "வேலைக்காரர் கூட்டத்துக்கு ஊட்டி கூடு கட்டுகின்றனர்; போர்வீரர் காக்கின்றனர்.",
            "Termites feed on wood, paper and cloth, which contain cellulose." to "செல்லுலோஸ் உள்ள மரம், காகிதம், துணியைக் கரையான்கள் உண்கின்றன.",
            "They weaken buildings, furniture and books, often from within and unseen." to "அவை கட்டிடங்கள், தளவாடங்கள், நூல்களை, பெரும்பாலும் உள்ளிருந்து, கண்ணுக்குத் தெரியாமல் வலுவிழக்கச் செய்கின்றன."),
        q("u6-household-insects", 2, "How are insects that damage books, cloth and wood controlled?", "நூல்கள், துணி, மரத்தைச் சேதப்படுத்தும் பூச்சிகள் எவ்வாறு கட்டுப்படுத்தப்படுகின்றன?",
            "Keep the store clean, dry and well ventilated." to "கிடங்கைத் தூய்மையாகவும் உலர்வாகவும் காற்றோட்டத்துடனும் வைத்தல்.",
            "Inspect books and clothes regularly and air them in the sun." to "நூல்களையும் துணிகளையும் வழக்கமாக ஆய்வு செய்து வெயிலில் காயவைத்தல்.",
            "Seal cracks and use treated or seasoned timber in buildings." to "விரிசல்களை அடைத்து, கட்டிடங்களில் சிகிச்சையளிக்கப்பட்ட அல்லது பதப்படுத்திய மரத்தைப் பயன்படுத்துதல்.",
            "Use physical barriers and traps before any chemical." to "எந்த வேதிப்பொருளுக்கும் முன் இயற்பியல் தடைகளையும் பொறிகளையும் பயன்படுத்துதல்.",
            "Any chemical treatment should follow official guidelines and be done by trained persons." to "எந்த வேதிச் சிகிச்சையும் அதிகாரபூர்வ வழிகாட்டுதல்களைப் பின்பற்றி பயிற்சி பெற்றவரால் செய்யப்பட வேண்டும்."),

        q("u6-pests-ipm", 1, "What is Integrated Pest Management? State its components.", "ஒருங்கிணைந்த பூச்சி மேலாண்மை என்றால் என்ன? அதன் கூறுகளைக் கூறுக.",
            "IPM combines several compatible methods to keep pests below the economic threshold." to "IPM பொருளாதார வாசலுக்குக் கீழே பீடைகளை வைத்திருக்கப் பல இணக்கமான முறைகளை இணைக்கிறது.",
            "Cultural methods include crop rotation, sanitation and resistant varieties." to "பண்பாட்டு முறைகள்: பயிர்ச் சுழற்சி, தூய்மை, எதிர்ப்பு ரகங்கள்.",
            "Mechanical and physical methods include hand-picking and traps." to "இயந்திர, இயற்பியல் முறைகள்: கையால் பொறுக்குதல், பொறிகள்.",
            "Biological methods use predators, parasitoids and microbial agents." to "உயிரியல் முறைகள்: வேட்டையாடிகள், ஒட்டுண்ணிக்கொல்லிகள், நுண்ணுயிர்க் காரணிகள்.",
            "Chemicals are used last, only when monitoring shows that they are needed." to "வேதிப்பொருட்கள் கடைசியில், கண்காணிப்பு தேவை எனக் காட்டினால் மட்டும் பயன்படுத்தப்படுகின்றன."),
        q("u6-pests-ipm", 2, "Why can the overuse of insecticides be harmful?", "பூச்சிக்கொல்லிகளை அதிகமாகப் பயன்படுத்துவது ஏன் தீங்கு தரலாம்?",
            "Repeated use selects resistant insects, so the poison stops working." to "மீண்டும் மீண்டும் பயன்படுத்துவது எதிர்ப்புள்ள பூச்சிகளைத் தேர்ந்தெடுக்கிறது; நஞ்சு பயனற்றதாகிறது.",
            "It kills natural enemies, which may cause a resurgence of the pest." to "இயற்கை எதிரிகளைக் கொல்கிறது; பீடை மீண்டும் பெருகலாம்.",
            "Secondary pests may rise to pest status when their enemies are killed." to "எதிரிகள் கொல்லப்படும்போது இரண்டாம் நிலைப் பீடைகள் பீடைநிலைக்கு உயரலாம்.",
            "Residues may remain on food and in soil and water." to "எச்சங்கள் உணவிலும் மண்ணிலும் நீரிலும் தங்கலாம்.",
            "Pollinators and other useful animals are poisoned." to "மகரந்தச் சேர்க்கையாளர்களும் பிற பயனுள்ள விலங்குகளும் நஞ்சூட்டப்படுகின்றன."),

        q("u6-cereal-pests", 1, "Describe the life history and damage of the yellow stem borer of rice.", "நெல்லின் மஞ்சள் தண்டுத் துளைப்பானின் வாழ்க்கை வரலாற்றையும் சேதத்தையும் விவரிக்க.",
            "It is Scirpophaga incertulas, a moth whose larva is the damaging stage." to "இது Scirpophaga incertulas என்ற அந்துப்பூச்சி; அதன் புழுவே சேதம் செய்யும் நிலை.",
            "The female lays egg masses covered with buff hairs near the leaf tips." to "பெண் ஓலை நுனி அருகே மஞ்சள் மயிர் மூடிய முட்டைத் திரள்களை இடுகிறது.",
            "The larva bores into the stem, feeds for about four weeks and pupates in the stem or stubble." to "புழு தண்டுக்குள் துளைத்து ஏறக்குறைய நான்கு வாரம் உண்டு, தண்டு அல்லது அடிக்கட்டையில் கூட்டுப்புழுவாகிறது.",
            "In the young crop it causes dead heart." to "இளம் பயிரில் இறந்த இதயத்தை உண்டாக்குகிறது.",
            "After ear formation it causes white ear with empty grains." to "கதிர் உருவான பின் வெற்றுத் தானியங்களுடன் வெண் கதிரை உண்டாக்குகிறது."),
        q("u6-cereal-pests", 2, "Describe the rice weevil and the protection of stored grain.", "அரிசிக் கூன்வண்டையும் சேமித்த தானியத்தின் பாதுகாப்பையும் விவரிக்க.",
            "Sitophilus oryzae is a small beetle with a long snout, and it is a primary storage pest." to "Sitophilus oryzae நீண்ட மூக்குள்ள சிறு வண்டு; முதல்நிலைச் சேமிப்புப் பீடை.",
            "The female lays one egg in a cavity chewed in a grain and seals it." to "பெண் தானியத்தில் கடித்த குழியில் ஒரு முட்டையிட்டு அடைக்கிறது.",
            "The larva and pupa develop inside the grain, so the infestation is hidden." to "புழுவும் கூட்டுப்புழுவும் தானியத்துக்குள் வளர்வதால் தொற்று மறைந்திருக்கிறது.",
            "Dry the grain well, clean the store and use sound structures." to "தானியத்தை நன்கு உலர்த்தி, கிடங்கைத் தூய்மைப்படுத்தி, நல்ல கட்டமைப்புகளைப் பயன்படுத்துதல்.",
            "Hermetic storage and regular inspection help; fumigation is for trained persons only." to "காற்றடைப்புச் சேமிப்பும் வழக்கமான ஆய்வும் உதவும்; புகைமூட்டுதல் பயிற்சி பெற்றோருக்கு மட்டுமே."),

        q("u6-crop-pests", 1, "Describe the coconut rhinoceros beetle and its management.", "தென்னை காண்டாமிருக வண்டையும் அதன் மேலாண்மையையும் விவரிக்க.",
            "Oryctes rhinoceros is a large dark beetle; the male has a horn on the head." to "Oryctes rhinoceros பெரிய கருமையான வண்டு; ஆணின் தலையில் கொம்பு உண்டு.",
            "The adult bores into the crown of the palm and causes V-shaped cuts in the fronds." to "முதிர்பூச்சி பனையின் கிரீடத்தில் துளைத்து ஓலைகளில் V வடிவ வெட்டுகளை உண்டாக்குகிறது.",
            "The grubs live in rotting plant matter such as manure and old trunks." to "குஞ்சுகள் சாணம், பழைய மரத்தடி போன்ற அழுகும் தாவரப் பொருளில் வாழ்கின்றன.",
            "Sanitation of the breeding sites and pheromone traps reduce the numbers." to "இனப்பெருக்க இடங்களின் தூய்மையும் ஃபெரோமோன் பொறிகளும் எண்ணிக்கையைக் குறைக்கின்றன.",
            "Metarhizium fungus and the nudivirus are used as biological agents." to "Metarhizium பூஞ்சையும் நியூடிவைரஸும் உயிரியல் காரணிகளாகப் பயன்படுகின்றன."),
        q("u6-crop-pests", 2, "Why has the diamondback moth become resistant to insecticides?", "வைர முதுகு அந்துப்பூச்சி பூச்சிக்கொல்லிகளுக்கு ஏன் எதிர்ப்பு பெற்றது?",
            "Plutella xylostella is a small moth whose larvae feed on cabbage-family crops." to "Plutella xylostella சிறிய அந்துப்பூச்சி; அதன் புழுக்கள் முட்டைக்கோசுக் குடும்பப் பயிர்களை உண்கின்றன.",
            "It has very many generations in a year, so resistance genes spread quickly." to "ஆண்டில் மிகப் பல தலைமுறைகள் இருப்பதால் எதிர்ப்பு மரபணுக்கள் விரைவாகப் பரவுகின்றன.",
            "The host crops are grown continuously and sprayed repeatedly." to "விருந்தோம்பிப் பயிர்கள் தொடர்ச்சியாக வளர்க்கப்பட்டு மீண்டும் மீண்டும் தெளிக்கப்படுகின்றன.",
            "Each spray selects the resistant survivors, which is selection pressure." to "ஒவ்வொரு தெளிப்பும் எதிர்ப்புடன் தப்பியவற்றைத் தேர்ந்தெடுக்கிறது; இதுவே தேர்வு அழுத்தம்.",
            "Rotating products and protecting natural enemies such as Cotesia slow resistance." to "பொருட்களை மாற்றுதலும் Cotesia போன்ற இயற்கை எதிரிகளைக் காத்தலும் எதிர்ப்பை மெதுவாக்கும்."),
        q("u6-chelicerata", 1, "Describe the external features of the scorpion.", "தேளின் வெளி அமைப்பை விவரிக்க.",
            "The body has a prosoma with a carapace and an opisthosoma." to "உடலில் காரபேசுடன் புரோசோமாவும் ஆப்பிஸ்தோசோமாவும் உள்ளன.",
            "The prosoma bears small chelicerae, large pincer-like pedipalps and four pairs of walking legs." to "புரோசோமா சிறிய செலிசெராக்கள், பெரிய இடுக்கி போன்ற பெடிபால்ப்கள், நான்கு இணை நடைக்கால்களைத் தாங்குகிறது.",
            "The opisthosoma has a broad pre-abdomen of seven segments and a narrow tail-like post-abdomen of five." to "ஆப்பிஸ்தோசோமாவில் ஏழு கண்டங்களுள்ள அகன்ற முன்வயிறும் ஐந்து கண்டங்களுள்ள குறுகிய வால் போன்ற பின்வயிறும் உள்ளன.",
            "The last segment bears the telson, a bulb with a curved sting and venom glands." to "கடைசிக் கண்டம் வளைந்த கொடுக்கும் நஞ்சுச் சுரப்பிகளும் உள்ள குமிழான டெல்சனைத் தாங்குகிறது.",
            "Comb-like pectines and book lungs lie on the underside; scorpions are viviparous." to "அடிப்பகுதியில் சீப்பு போன்ற பெக்டின்களும் நூல் நுரையீரல்களும் உள்ளன; தேள்கள் குட்டி ஈனுபவை."),
        q("u6-chelicerata", 2, "Write notes on the horseshoe crab and the ticks and mites.", "குதிரைலாட நண்டு, உண்ணிகள், சிற்றுண்ணிகள் பற்றிக் குறிப்பு எழுதுக.",
            "The horseshoe crab, Limulus, belongs to the class Merostomata and is called a living fossil." to "குதிரைலாட நண்டு லிமுலஸ் மெரோஸ்டோமாட்டா வகுப்பைச் சேர்ந்தது; உயிருள்ள புதைபடிவம் எனப்படுகிறது.",
            "It has a horseshoe-shaped carapace, book gills, a tail spine (telson) and blue blood with haemocyanin." to "குதிரைலாட காரபேஸ், நூல் செவுள்கள், வால்முள் (டெல்சன்), ஹீமோசயனினுடன் நீல இரத்தம் உள்ளன.",
            "Its blood cells yield Limulus lysate, used to test injections for bacterial endotoxin." to "அதன் இரத்த செல்கள் லிமுலஸ் லைசேட் தருகின்றன; ஊசி மருந்துகளில் பாக்டீரியா எண்டோடாக்சினைச் சோதிக்கப் பயன்படுகிறது.",
            "Ticks and mites (Acari) have fused body regions and a six-legged larva." to "உண்ணிகள், சிற்றுண்ணிகளுக்கு (ஏகாரி) இணைந்த உடல் பகுதிகளும் ஆறு கால் புழுவும் உண்டு.",
            "Ticks spread Kyasanur Forest disease; chigger mites spread scrub typhus; Sarcoptes causes scabies." to "உண்ணிகள் கியாசனூர் காட்டு நோயைப் பரப்புகின்றன; சிக்கர் சிற்றுண்ணிகள் ஸ்க்ரப் டைஃபஸைப் பரப்புகின்றன; Sarcoptes சிரங்கை உண்டாக்குகிறது."),

        q("u6-myriapoda", 1, "Describe the centipede Scolopendra.", "நூறுகாலி ஸ்கோலோபெண்ட்ராவை விவரிக்க.",
            "It is a flattened, carnivorous, nocturnal arthropod with a head and a long trunk." to "இது தலையும் நீண்ட உடற்பகுதியும் உள்ள தட்டையான, ஊனுண்ணி, இரவில் செயல்படும் கணுக்காலி.",
            "Each trunk segment has one pair of legs, usually twenty-one pairs in all." to "ஒவ்வொரு உடற்கண்டத்திலும் ஒரு இணை கால்; பொதுவாக மொத்தம் இருபத்தொரு இணை.",
            "The first pair of trunk legs form poison claws, the forcipules, with venom glands." to "முதல் இணை உடற்கால்கள் நஞ்சுச் சுரப்பிகளுடன் நஞ்சுக் கொடுக்குகளான ஃபோர்சிபுல்களாக உள்ளன.",
            "Respiration is by tracheae with spiracles, and excretion by Malpighian tubules." to "சுவாசம் ஸ்பைராக்கிள்களுடன் மூச்சுக்குழல்களாலும் கழிவு நீக்கம் மால்பீஜியன் குழல்களாலும் நடைபெறுகிறது.",
            "The female guards her eggs, and the young hatch with all segments (epimorphosis)." to "பெண் முட்டைகளைக் காக்கிறது; குஞ்சுகள் எல்லாக் கண்டங்களுடனும் பொரிகின்றன (எபிமார்போசிஸ்)."),
        q("u6-myriapoda", 2, "Distinguish a millipede from a centipede.", "ஆயிரங்காலியை நூறுகாலியிலிருந்து வேறுபடுத்துக.",
            "A millipede is cylindrical, and a centipede is flattened." to "ஆயிரங்காலி உருளை வடிவம்; நூறுகாலி தட்டையானது.",
            "A millipede has two pairs of legs on most segments, which are diplosegments, and a centipede has one pair." to "ஆயிரங்காலிக்கு பெரும்பாலான கண்டங்களில் இரு இணை கால்கள் (டிப்ளோசெக்மெண்டுகள்); நூறுகாலிக்கு ஒரு இணை.",
            "A millipede has no poison claws and defends itself by coiling and by stink glands." to "ஆயிரங்காலிக்கு நஞ்சுக் கொடுக்குகள் இல்லை; சுருளுதல், நாற்றச் சுரப்பிகளால் தற்காக்கிறது.",
            "A millipede is a slow detritivore, and a centipede is a fast carnivore." to "ஆயிரங்காலி மெதுவான கழிவுண்ணி; நூறுகாலி வேகமான ஊனுண்ணி.",
            "A millipede shows anamorphosis, and a centipede, epimorphosis." to "ஆயிரங்காலி அனாமார்போசிஸ் காட்டுகிறது; நூறுகாலி எபிமார்போசிஸ்."),

        q("u6-minor-arthropods", 1, "Describe the tardigrade and explain cryptobiosis.", "டார்டிகிரேடை விவரித்து கிரிப்டோபயோசிஸை விளக்குக.",
            "Tardigrades are minute animals of moss, soil and water with four pairs of stubby clawed legs." to "டார்டிகிரேடுகள் பாசி, மண், நீரின் நுண்ணிய விலங்குகள்; நகங்களுடன் நான்கு இணை குட்டை கால்கள்.",
            "They pierce plant cells or small animals with stylets and suck out the contents." to "ஸ்டைலெட்டுகளால் தாவர செல்கள் அல்லது சிறு விலங்குகளைத் துளைத்து உள்ளடக்கத்தை உறிஞ்சுகின்றன.",
            "In drying, the animal shrinks into a dry barrel-shaped tun." to "உலரும்போது விலங்கு உலர்ந்த பீப்பாய் வடிவ டன்னாகச் சுருங்குகிறது.",
            "Metabolism falls to an undetectable level; this is cryptobiosis, here anhydrobiosis." to "வளர்சிதை மாற்றம் கண்டறிய முடியாத அளவுக்குக் குறைகிறது; இது கிரிப்டோபயோசிஸ், இங்கு அன்ஹைட்ரோபயோசிஸ்.",
            "Protective sugars and proteins preserve the cells, and the animal revives when it is wetted." to "பாதுகாப்புச் சர்க்கரைகளும் புரதங்களும் செல்களைக் காக்கின்றன; நனைந்ததும் விலங்கு உயிர் பெறுகிறது."),
        q("u6-minor-arthropods", 2, "Describe the Pentastomida and their life cycle.", "பென்டாஸ்டோமிடாவையும் அவற்றின் வாழ்க்கைச் சுழற்சியையும் விவரிக்க.",
            "Pentastomids are tongue worms that live in the respiratory tracts of vertebrates, chiefly reptiles." to "பென்டாஸ்டோமிடுகள் முதுகெலும்பிகளின், முக்கியமாக ஊர்வனவற்றின், சுவாசப் பாதைகளில் வாழும் நாக்குப் புழுக்கள்.",
            "The body is annulated and has two pairs of anchoring hooks near the mouth." to "உடல் வளையங்களுடையது; வாய் அருகே இரு இணை நிலைநிறுத்தும் கொக்கிகள் உண்டு.",
            "The eggs pass out of the final host and are eaten by an intermediate host." to "முட்டைகள் இறுதி விருந்தோம்பியிலிருந்து வெளியேறி இடைநிலை விருந்தோம்பியால் உண்ணப்படுகின்றன.",
            "The larva bores through the gut, encysts in the viscera and moults." to "புழு குடலைத் துளைத்து, உள்ளுறுப்புகளில் உறையிட்டு தோலுரிக்கிறது.",
            "The final host eats the intermediate host, and the larva moves to the respiratory tract and matures." to "இறுதி விருந்தோம்பி இடைநிலை விருந்தோம்பியை உண்கிறது; புழு சுவாசப் பாதைக்குச் சென்று முதிர்கிறது."),
    ).groupBy { it.chapterId }
}
